-- Dadyoom original literacy1 exercises. Preserve teacher records and prior 25 MCQs.
-- All 25 prompts are based on original supporting drafts; pending educational editorial review.
DO $guard$ BEGIN
 IF (SELECT count(*) FROM public.lesson_activities WHERE content->>'origin'='DADYOOM_BH_CONTINUING_LITERACY1_MCQ_V1')<>25
 THEN RAISE EXCEPTION 'Preexisting BH literacy1 MCQs must equal 25'; END IF;
END $guard$;
WITH payload AS (SELECT value AS j FROM jsonb_array_elements($LESSONS$[{"order":1,"lessonTitle":"القراءة: الدرس الأول: أسرة جاسم (1)","format":"ordering","prompt":"رتّب تقديم جاسم لنفسه.","words":["أنا","جاسم"],"practice":"اقرأ «أنا جاسم. هذه أسرتي»، ثم قدّم نفسك واذكر أحد أفراد أسرتك."},{"order":2,"lessonTitle":"التراكيب اللغوية: الجمل القصيرة (من كلمتين)","format":"fill_blank","prompt":"أكمل جملة مفيدة من كلمتين.","sentence":"___ واسع.","options":["البيت","في","على"],"correct":"البيت","practice":"اكتب جملتين مفيدتين من كلمتين عن بيتك أو مدرستك."},{"order":3,"lessonTitle":"الإملاء والخط: رسم الكلمات بحسب التنقيط؛ مراعاة الحركات والمدود بأنواعها","format":"fill_blank","prompt":"ميز حرف التاء من عدد نقاطه.","sentence":"الحرف ذو النقطتين فوقه هو ___ .","options":["ت","ب","ث"],"correct":"ت","practice":"اكتب «باب» و«بيت» مع ضبط مواقع النقط والمدود."},{"order":4,"lessonTitle":"القراءة: الدرس الثاني: أسرة جاسم (2)","format":"ordering","prompt":"رتب حدث عودة الأم.","words":["عادت","أمي","إلى","البيت"],"practice":"اقرأ «عادت أمي إلى البيت. جلس أبي قرب الباب»، وحدد الشخص والمكان."},{"order":5,"lessonTitle":"التراكيب اللغوية: الجمل القصيرة (من كلمتين أو ثلاث)","format":"ordering","prompt":"وسّع الجملة بظرف زمان.","words":["جاسم","يكتب","اليوم"],"practice":"اكتب جملة عن عمل تقوم به اليوم من ثلاث كلمات."},{"order":6,"lessonTitle":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرف المستهدف (ج)","format":"fill_blank","prompt":"اختر الصوت الأول لكلمة جمل.","sentence":"تبدأ كلمة «جمل» بحرف ___ .","options":["ج","ح","خ"],"correct":"ج","practice":"حلّل «دجاج» إلى حروف، ثم انطق حرف الجيم مع الحركات الثلاث."},{"order":7,"lessonTitle":"القراءة: الدرس الثالث: زيارة إلى بيت جاسم (1)","format":"ordering","prompt":"رتب جملة الزيارة.","words":["زار","سامي","بيت","جاسم"],"practice":"اقرأ جملة الزيارة ثم أخبر قريبًا بكيفية استقبال الضيف."},{"order":8,"lessonTitle":"التراكيب اللغوية: أسلوب الاستفهام","format":"fill_blank","prompt":"أكمل سؤالًا عن المكان.","sentence":"___ يقع مركز التعلم؟","options":["أين","من","متى"],"correct":"أين","practice":"اكتب سؤالًا عن موعد الدرس وسؤالًا آخر عن مكان المكتبة."},{"order":9,"lessonTitle":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرف المستهدف (م)؛ رسم الكلمات بحسب التنقيط","format":"fill_blank","prompt":"حدد الحرف الأخير من قلم.","sentence":"آخر حرف في «قلم» هو ___ .","options":["م","ق","ل"],"correct":"م","practice":"اكتب «ماء» و«قلم» وضع دائرة حول الميم في كل كلمة."},{"order":10,"lessonTitle":"القراءة: الدرس الرابع: زيارة إلى بيت جاسم (2)","format":"ordering","prompt":"رتب ختام الزيارة.","words":["شكر","سامي","جاسمًا"],"practice":"اكتب جملة شكر مناسبة تقولها عند مغادرة بيت صديق."},{"order":11,"lessonTitle":"التراكيب اللغوية: الفعل الماضي؛ الجملة الفعلية","format":"ordering","prompt":"كوّن جملة بالفعل الماضي.","words":["كتب","جاسم","رسالة"],"practice":"اكتب عملًا أنجزته أمس، مستخدمًا فعلًا ماضيًا."},{"order":12,"lessonTitle":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (د، ر)؛ تركيب كلمات من الحروف والمقاطع؛ رسم الكلمات بحسب التنقيط","format":"fill_blank","prompt":"حدد أول حرف في دار.","sentence":"تبدأ كلمة «دار» بحرف ___ .","options":["د","ر","ذ"],"correct":"د","practice":"ركب «دار» من حروفها، ثم انسخ «ورد» وبيّن شكل الراء."},{"order":13,"lessonTitle":"القراءة: الدرس الخامس: رحلة","format":"ordering","prompt":"رتب جملة عن وسيلة النقل.","words":["ركبت","الأسرة","الحافلة"],"practice":"اقرأ عن الرحلة إلى الحديقة ثم سمِّ وسيلة النقل التي تستخدمها."},{"order":14,"lessonTitle":"التراكيب اللغوية: استعمال بعض ظروف الزمان والمكان (داخل، خارج، بعد، قبل)","format":"fill_blank","prompt":"اختر ظرف مكان صحيحًا.","sentence":"وضعتُ القلم ___ الحقيبة.","options":["داخل","بعد","قبل"],"correct":"داخل","practice":"اكتب جملة فيها «خارج» للمكان وجملة فيها «قبل» للوقت."},{"order":15,"lessonTitle":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (خ، ظ)؛ تركيب كلمات من الحروف والمقاطع؛ رسم الكلمات بحسب التنقيط","format":"fill_blank","prompt":"ميز الحرف الأول من خبز.","sentence":"تبدأ كلمة «خبز» بحرف ___ .","options":["خ","ح","ظ"],"correct":"خ","practice":"اكتب «خبز» و«ظل» وانتبه إلى نقاط حرفي الخاء والظاء."},{"order":16,"lessonTitle":"القراءة: الدرس السادس: سهرة عائلية","format":"ordering","prompt":"رتب حدث الاستماع في السهرة.","words":["استمع","جاسم","إلى","القصة"],"practice":"اقرأ سؤال الأب «ماذا نقرأ؟» واكتب جوابًا مهذبًا."},{"order":17,"lessonTitle":"التراكيب اللغوية: الحوار","format":"ordering","prompt":"ركب تحية تبدأ بها حوارًا.","words":["السلام","عليكم"],"practice":"اكتب حوارًا من سؤال وجواب يبدأ بالتحية في مركز التعلم."},{"order":18,"lessonTitle":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (ف، ق)؛ تركيب كلمات من الحروف والمقاطع؛ كتابة الكلمات بحسب الصور","format":"fill_blank","prompt":"حدّد حرف القاف في قفل.","sentence":"تبدأ كلمة «قفل» بحرف ___ .","options":["ق","ف","ك"],"correct":"ق","practice":"انسخ «قفل» و«فصل» وراجع عدد النقط فوق الفاء والقاف."},{"order":19,"lessonTitle":"القراءة: الدرس السابع: بيت جاسم","format":"ordering","prompt":"رتب وصف باب البيت.","words":["للبيت","باب","واسع"],"practice":"صف باب بيتك أو نافذته بجملة مفهومة."},{"order":20,"lessonTitle":"التراكيب اللغوية: استعمال الضمير (أنا)","format":"fill_blank","prompt":"أكمل بضمير المتكلم.","sentence":"___ أقرأ في المساء.","options":["أنا","هو","هي"],"correct":"أنا","practice":"اكتب جملتين تبدآن بـ«أنا» تتعلقان بعملك أو تعلمك."},{"order":21,"lessonTitle":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (ث، ن)؛ تركيب كلمات من الحروف والمقاطع","format":"fill_blank","prompt":"اختر الحرف ذا النقاط الثلاث.","sentence":"ثلاث نقاط فوق حرف ___ .","options":["ث","ت","ن"],"correct":"ث","practice":"اكتب «ثوب» و«نهر» وحدد موضع النقط في كل منهما."},{"order":22,"lessonTitle":"القراءة: الدرس الثامن: حسن جار جاسم","format":"ordering","prompt":"رتب موقفًا عن مساعدة الجار.","words":["ساعد","حسن","جاره","جاسمًا"],"practice":"اقرأ الموقف ثم اكتب عملًا حسنًا تقدمه لجارك."},{"order":23,"lessonTitle":"التراكيب اللغوية: استعمال حروف الجر","format":"fill_blank","prompt":"اختر حرف الجر الدال على الاتجاه.","sentence":"ذهبتُ ___ السوق.","options":["إلى","في","من"],"correct":"إلى","practice":"اكتب جملة فيها «في» وأخرى فيها «على»."},{"order":24,"lessonTitle":"الإملاء والخط: تحليل الكلمات إلى حروف ومقاطع؛ الحرفان المستهدفان (س، ك)؛ تركيب كلمات من الحروف والمقاطع؛ كتابة الكلمات بحسب الصور؛ مراعاة التضعيف (الشدة) في الكلمات","format":"fill_blank","prompt":"حدد الحرف الأول من كتاب.","sentence":"تبدأ كلمة «كتاب» بحرف ___ .","options":["ك","س","ق"],"correct":"ك","practice":"اكتب «كتاب» و«سَلَّمَ»، ثم حدّد الكاف وموضع الشدة."},{"order":25,"lessonTitle":"مراجعة عامة","format":"ordering","prompt":"رتب جملة ختامية للمراجعة.","words":["أنا","أقرأ","كتابًا"],"practice":"اكتب جملة بـ«أنا»، ثم سؤالًا بـ«أين»، ثم كلمة ذات حرف بثلاث نقاط."}]$LESSONS$::jsonb)),
target AS (
 SELECT mcq.lesson_id,p.j FROM payload p
 JOIN public.lesson_activities mcq ON mcq.content->>'origin'='DADYOOM_BH_CONTINUING_LITERACY1_MCQ_V1'
 JOIN public.lessons l ON l.id=mcq.lesson_id AND l.title=p.j->>'lessonTitle'
),
variants AS (SELECT t.lesson_id,t.j,v.variant FROM target t CROSS JOIN (VALUES ('graded'),('practice')) v(variant))
INSERT INTO public.lesson_activities
(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
SELECT v.lesson_id,
 CASE WHEN variant='graded' THEN 'طبّق المهارة: إكمال أو ترتيب' ELSE 'تطبيق ذاتي: قراءة أو كتابة' END,
 CASE WHEN variant='practice' THEN (CASE WHEN v.j->>'lessonTitle' LIKE 'القراءة:%' THEN 'reading' ELSE 'writing' END)
      WHEN v.j->>'format'='ordering' THEN 'matching' ELSE 'fill_blank' END,
 CASE WHEN variant='graded' THEN 'اختر الإجابة أو رتّب الكلمات ثم تحقّق منها.' ELSE 'نشاط تطبيقي غير مقيم آليًا. اقرأ أو اكتب أولًا، ثم أثبت إتمام المحاولة.' END,
 CASE WHEN variant='practice' THEN jsonb_build_object('origin','DADYOOM_BH_CONTINUING_LITERACY1_SKILLS_V2','variant',variant,'text',v.j->>'practice','editorial_review','required','book_text_copied',false)
      WHEN v.j->>'format'='ordering' THEN jsonb_build_object('origin','DADYOOM_BH_CONTINUING_LITERACY1_SKILLS_V2','variant',variant,'words',v.j->'words','editorial_review','required','book_text_copied',false)
      ELSE jsonb_build_object('origin','DADYOOM_BH_CONTINUING_LITERACY1_SKILLS_V2','variant',variant,'items',jsonb_build_array(jsonb_build_object('sentence',v.j->>'sentence','options',v.j->'options')),'editorial_review','required','book_text_copied',false) END,
 CASE WHEN variant='graded' THEN 2 ELSE 3 END,
 CASE WHEN variant='graded' THEN 5 ELSE 0 END,
 true, CASE WHEN variant='graded' THEN 'assessment' ELSE 'practice' END,
 CASE WHEN variant='graded' THEN v.j->>'prompt' ELSE v.j->>'practice' END,
 CASE WHEN variant='practice' THEN jsonb_build_object('grading_mode','completion_only_reference')
      WHEN v.j->>'format'='ordering' THEN jsonb_build_object('correct_words',v.j->'words')
      ELSE jsonb_build_object('answers',jsonb_build_array(v.j->>'correct')) END,
 false
FROM variants v
WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities old WHERE old.lesson_id=v.lesson_id
 AND old.content->>'origin'='DADYOOM_BH_CONTINUING_LITERACY1_SKILLS_V2' AND old.content->>'variant'=variant);
